using System.Text.Json;
using Clary.Api.Identity;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;
public sealed class AssetConfigurationRepository(NpgsqlDataSource database) {
 public static readonly IReadOnlyList<string> Icons=Array.AsReadOnly(new[]{"Box","Package","Laptop","Monitor","Printer","Server","Router","Wifi","Headphones","Keyboard","Mouse","Smartphone","Tablet","Camera","Video","Mic","Speaker","Cable","HardDrive","Cpu","Wrench","Hammer","Drill","Car","Truck","Bike","Armchair","Sofa","Lightbulb","Briefcase"});
 static readonly (string Code,string Icon)[] Defaults=[("Computer","Laptop"),("Printer","Printer"),("Monitor","Monitor"),("Network","Router"),("Accessory","Package")];
 static string Label(string? s,int max,bool required=true){s=s?.Trim();if(string.IsNullOrEmpty(s)){if(required)throw new ArgumentException("A name is required.");return "";}if(s.Length>max)throw new ArgumentException($"Text must be up to {max} characters.");return s;}
 static void Revision(Guid? id,int? revision){if(id is not null&&revision is null or <1)throw new ArgumentException("Expected revision is required.");if(id is null&&revision is not null)throw new ArgumentException("New definitions cannot supply a revision.");}
 static NpgsqlCommand Query(NpgsqlConnection c,NpgsqlTransaction tx,CompanyContext ctx,string sql){var q=new NpgsqlCommand(sql,c,tx);q.Parameters.AddWithValue("company",ctx.CompanyId);return q;}
 public static async Task SeedDefaultsAsync(NpgsqlConnection c,NpgsqlTransaction tx,Guid companyId,CancellationToken ct){for(var i=0;i<Defaults.Length;i++){await using var q=new NpgsqlCommand("INSERT INTO asset_types(id,company_id,code,name,icon,sort_order) VALUES(@id,@company,@code,@code,@icon,@sort) ON CONFLICT(company_id,code) DO NOTHING",c,tx);q.Parameters.AddWithValue("id",Guid.NewGuid());q.Parameters.AddWithValue("company",companyId);q.Parameters.AddWithValue("code",Defaults[i].Code);q.Parameters.AddWithValue("icon",Defaults[i].Icon);q.Parameters.AddWithValue("sort",i);await q.ExecuteNonQueryAsync(ct);}foreach(var name in new[]{"Brand","Model"}){await using var q=new NpgsqlCommand("INSERT INTO asset_fields(id,company_id,name,kind,help_text,sort_order) SELECT @id,@company,@name,'shortText',@help,@sort WHERE NOT EXISTS(SELECT 1 FROM asset_fields WHERE company_id=@company AND asset_type_id IS NULL AND lower(btrim(name))=lower(@name))",c,tx);q.Parameters.AddWithValue("id",Guid.NewGuid());q.Parameters.AddWithValue("company",companyId);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("help",name=="Brand"?"Manufacturer, for example Asus":"Product model, for example ProArt P16");q.Parameters.AddWithValue("sort",name=="Brand"?-2:-1);await q.ExecuteNonQueryAsync(ct);}}
 internal static async Task<AssetConfigurationDto> Read(NpgsqlConnection c,NpgsqlTransaction tx,CompanyContext ctx,CancellationToken ct){
  var types=new List<AssetTypeDto>();var fields=new List<AssetFieldDto>();
  await using(var q=Query(c,tx,ctx,"SELECT id,code,name,icon,active,sort_order,revision,categories::text FROM asset_types WHERE company_id=@company ORDER BY sort_order,name,id")){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))types.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetBoolean(4),r.GetInt32(5),r.GetInt32(6),JsonSerializer.Deserialize<string[]>(r.GetString(7))!));}
  await using(var q=Query(c,tx,ctx,"SELECT id,asset_type_id,name,kind,help_text,required,active,sort_order,choices::text,revision FROM asset_fields WHERE company_id=@company ORDER BY sort_order,name,id")){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))fields.Add(new(r.GetGuid(0),r.IsDBNull(1)?null:r.GetGuid(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetBoolean(5),r.GetBoolean(6),r.GetInt32(7),JsonSerializer.Deserialize<string[]>(r.GetString(8))!,r.GetInt32(9)));}return new(types,fields,Icons);
 }
 public async Task<AssetConfigurationDto> GetAsync(CompanyContext context,CancellationToken ct){await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(c,tx,context,CompanyCapability.OwnInventory,ct);var result=await Read(c,tx,context,ct);await tx.CommitAsync(ct);return result;}
 static async Task Limit(NpgsqlConnection c,NpgsqlTransaction tx,CompanyContext ctx,string table,bool active,bool wasActive,CancellationToken ct){if(!active||wasActive)return;await using var q=Query(c,tx,ctx,$"SELECT count(*) FROM {table} WHERE company_id=@company AND active");if((long)(await q.ExecuteScalarAsync(ct))!>=100)throw new ArgumentException("A company can have at most 100 active definitions of each kind.");}
 public async Task<AssetTypeDto> SaveTypeAsync(CompanyContext context,Guid? id,AssetTypeInput input,CancellationToken ct){
  Revision(id,input.Revision);var name=Label(input.Name,100);if(!Icons.Contains(input.Icon,StringComparer.Ordinal))throw new ArgumentException("Choose an icon from the palette.");
  await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(c,tx,context,CompanyCapability.Settings,ct);var config=await Read(c,tx,context,ct);var before=id is null?null:config.Types.FirstOrDefault(t=>t.Id==id)??throw new InventoryMissing();if(before is not null&&before.Revision!=input.Revision)throw new InventoryConflict("Configuration changed or referenced field structure cannot change.");
  if(config.Types.Any(t=>t.Id!=id&&string.Equals(t.Name,name,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("A type with this name already exists.");await Limit(c,tx,context,"asset_types",input.Active,before?.Active??false,ct);
  var categories=(input.Categories??before?.Categories??[]).Select(x=>Label(x,100)).ToArray();if(categories.Length>100||categories.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=categories.Length)throw new ArgumentException("Categories must contain up to 100 unique names.");var key=id??Guid.NewGuid();var result=new AssetTypeDto(key,before?.Code??"custom-"+key.ToString("N"),name,input.Icon,input.Active,input.SortOrder,(before?.Revision??0)+1,categories);
  await using(var q=Query(c,tx,context,id is null?"INSERT INTO asset_types(id,company_id,code,name,icon,active,sort_order,revision,categories) VALUES(@id,@company,@code,@name,@icon,@active,@sort,@revision,@categories)":"UPDATE asset_types SET name=@name,icon=@icon,active=@active,sort_order=@sort,revision=@revision,categories=@categories WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("id",key);q.Parameters.AddWithValue("code",result.Code);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("icon",input.Icon);q.Parameters.AddWithValue("active",input.Active);q.Parameters.AddWithValue("sort",input.SortOrder);q.Parameters.AddWithValue("revision",result.Revision);q.Parameters.AddWithValue("categories",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(categories));await q.ExecuteNonQueryAsync(ct);}
  await AuditRepository.AppendAsync(c,tx,context,before is null?"Created":"Updated","asset-type",key,before,result,ct);await tx.CommitAsync(ct);return result;
 }
 public async Task<AssetFieldDto> SaveFieldAsync(CompanyContext context,Guid? id,AssetFieldInput input,CancellationToken ct){
  Revision(id,input.Revision);var name=Label(input.Name,100);var help=Label(input.HelpText,500,false);if(input.Kind is not("shortText" or "longText" or "number" or "date" or "boolean" or "choice"))throw new ArgumentException("Choose a valid field kind.");
  var choices=(input.Choices??[]).Select(x=>Label(x,100)).ToArray();if(input.Kind=="choice"&&(choices.Length is <1 or >100||choices.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=choices.Length)||input.Kind!="choice"&&choices.Length>0)throw new ArgumentException("Choices must contain 1 to 100 unique values for a choice field only.");
  await using var c=await database.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(c,tx,context,CompanyCapability.Settings,ct);var config=await Read(c,tx,context,ct);var before=id is null?null:config.Fields.FirstOrDefault(f=>f.Id==id)??throw new InventoryMissing();if(before is not null&&before.Revision!=input.Revision)throw new InventoryConflict("Configuration changed or referenced field structure cannot change.");
  if(input.AssetTypeId is Guid type&&!config.Types.Any(t=>t.Id==type&&(t.Active||before?.AssetTypeId==type)))throw new ArgumentException("Choose a type in this company.");if(config.Fields.Any(f=>f.Id!=id&&f.AssetTypeId==input.AssetTypeId&&string.Equals(f.Name,name,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("A field with this name already exists in this scope.");
  if(before is not null&&(before.Kind!=input.Kind||before.AssetTypeId!=input.AssetTypeId)){await using var used=Query(c,tx,context,"SELECT 1 FROM inventory_assets WHERE company_id=@company AND custom_fields ? @field LIMIT 1");used.Parameters.AddWithValue("field",before.Id.ToString());if(await used.ExecuteScalarAsync(ct) is not null)throw new InventoryConflict("Configuration changed or referenced field structure cannot change.");}
  await Limit(c,tx,context,"asset_fields",input.Active,before?.Active??false,ct);var key=id??Guid.NewGuid();var result=new AssetFieldDto(key,input.AssetTypeId,name,input.Kind,help==""?null:help,input.Required,input.Active,input.SortOrder,choices,(before?.Revision??0)+1);
  await using(var q=Query(c,tx,context,id is null?"INSERT INTO asset_fields(id,company_id,asset_type_id,name,kind,help_text,required,active,sort_order,choices,revision) VALUES(@id,@company,@type,@name,@kind,@help,@required,@active,@sort,@choices,@revision)":"UPDATE asset_fields SET asset_type_id=@type,name=@name,kind=@kind,help_text=@help,required=@required,active=@active,sort_order=@sort,choices=@choices,revision=@revision WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("id",key);q.Parameters.AddWithValue("type",NpgsqlDbType.Uuid,(object?)result.AssetTypeId??DBNull.Value);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("kind",input.Kind);q.Parameters.AddWithValue("help",NpgsqlDbType.Text,(object?)result.HelpText??DBNull.Value);q.Parameters.AddWithValue("required",input.Required);q.Parameters.AddWithValue("active",input.Active);q.Parameters.AddWithValue("sort",input.SortOrder);q.Parameters.AddWithValue("choices",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(choices));q.Parameters.AddWithValue("revision",result.Revision);await q.ExecuteNonQueryAsync(ct);}
  await AuditRepository.AppendAsync(c,tx,context,before is null?"Created":"Updated","asset-field",key,before,result,ct);await tx.CommitAsync(ct);return result;
 }
}



